import itertools
from pysat.formula import CNF
from pysat.solvers import Glucose3

n = 8
all_edges = [(i, j) for i in range(n) for j in range(i+1, n)]

edge_var = {e: idx+1 for idx, e in enumerate(all_edges)}
var_edge = {idx+1: e for idx, e in enumerate(all_edges)}

cnf = CNF()

# Fixed edges
fixed_edges = [(0,4), (0,7), (2,4)]
for e in fixed_edges:
    cnf.append([edge_var[e]])

# Degree constraints: each vertex must have exactly degree 4
for v in range(n):
    incident_edges = [e for e in all_edges if v in e]
    vars_incident = [edge_var[e] for e in incident_edges]

    # At most 4: no subset of 5 can all be true
    for combo in itertools.combinations(vars_incident, 5):
        cnf.append([-v for v in combo])

    # At least 4: at most 3 can be false, i.e., no subset of (len-3) can all be false
    for combo in itertools.combinations(vars_incident, len(incident_edges) - 3):
        cnf.append([v for v in combo])

# Girth constraints: no 3-cycles (triangles) - girth >= 4 means no triangles
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            cnf.append([-edge_var[(i,j)], -edge_var[(i,k)], -edge_var[(j,k)]])

print(f"Total clauses: {len(cnf.clauses)}")

solver = Glucose3()
solver.append_formula(cnf)

result = solver.solve()
print(f"Satisfiable: {result}")

if result:
    model = solver.get_model()
    solution_edges = [var_edge[v] for v in model if v > 0]
    print(f"Solution edges: {sorted(solution_edges)}")
    print(f"Number of edges: {len(solution_edges)}")

    # Verify degrees
    deg = [0]*n
    for u,v in solution_edges:
        deg[u] += 1
        deg[v] += 1
    print(f"Degrees: {deg}")

    # Verify no triangles
    tri_found = False
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                if (i,j) in solution_edges and (i,k) in solution_edges and (j,k) in solution_edges:
                    print(f"Triangle found: {i},{j},{k}")
                    tri_found = True
    if not tri_found:
        print("No triangles found.")

    # Check girth
    # Find shortest cycle
    # Build adjacency
    adj = {v: set() for v in range(n)}
    for u,v in solution_edges:
        adj[u].add(v)
        adj[v].add(u)

    # BFS to find shortest cycle
    min_cycle = float('inf')
    for start in range(n):
        # BFS from start
        dist = {start: 0}
        parent = {start: -1}
        queue = [start]
        while queue:
            v = queue.pop(0)
            for nb in adj[v]:
                if nb not in dist:
                    dist[nb] = dist[v] + 1
                    parent[nb] = v
                    queue.append(nb)
                elif nb != parent.get(v, -1) and dist[nb] <= dist[v]:
                    # Found a cycle
                    cycle_len = dist[v] + dist[nb] + 1
                    if cycle_len < min_cycle:
                        min_cycle = cycle_len

    print(f"Shortest cycle length (girth): {min_cycle}")
else:
    print("UNSATISFIABLE")
